inputs = ['bigwjj', 'fcub', 'dejuv', 'yx', 'juxi']
outputs = ['kigwiiii', 'fcuk', 'dawuxei', 'iix', 'iiuxi']

# Analyze each transformation
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{out}'")

    # Let's look at character by character differences
    print(f"  Length: {len(inp)} -> {len(out)}")

    # Find where they differ
    diff_positions = []
    for j, (char_in, char_out) in enumerate(zip(inp, out)):
        if char_in != char_out:
            diff_positions.append((j, char_in, char_out))

    if len(inp) != len(out):
        # Check remaining characters
        if len(inp) > len(out):
            for j in range(len(out), len(inp)):
                diff_positions.append((j, inp[j], None))
        else:
            for j in range(len(inp), len(out)):
                diff_positions.append((j, None, out[j]))

    print(f"  Differences at positions: {diff_positions}")
    print()

